document.querySelectorAll(".chips, .map-filters").forEach(t=>{t.addEventListener("click",e=>{const c=e.target.closest(".chip");c&&(t.querySelectorAll(".chip").forEach(t=>t.classList.remove("active")),c.classList.add("active"))})}),document.querySelectorAll(".btn-go, .btn-go-big").forEach(t=>{t.addEventListener("click",e=>{e.stopPropagation(),t.classList.toggle("going"),t.textContent=t.classList.contains("going")?"Вы идёте":"Пойду"})});